SELECT , u.real_name AS counselor_name FROM workflow_minutes w LEFT JOIN sys_user u ON w.counselor_id = u.id
AND w.title LIKE CONCAT('%', #{title}, '%') AND w.category = #{category} AND w.location LIKE CONCAT('%', #{location}, '%') AND w.counselor_id = #{counselorId}
ORDER BY w.meeting_date DESC, w.id DESC

mapper.update:
UPDATE workflow_minutes
title = #{title}, category = #{category}, content = #{content}, participants = #{participants}, meeting_date = #{meetingDate}, location = #{location}, summary = #{summary}, counselor_id = #{counselorId},
WHERE id = #{id}
